import React from 'react';
import {Button, ToasterComponent, ToasterProvider} from '@gravity-ui/uikit';
import {toaster} from '@gravity-ui/uikit/toaster-singleton';

let toastCounter = 0;

export function App() {
  const handleClick = () => {
    toastCounter += 1;
    toaster.add({
      name: `toast-${toastCounter}`,
      title: 'Уведомление',
      content: 'Это всплывающее уведомление.',
      theme: 'success',
      autoHiding: 4000,
    });
  };

  return (
    <ToasterProvider toaster={toaster}>
      <Button view="outlined" size="m" onClick={handleClick} style={{position: 'fixed', right: 16, bottom: 16}}>
        Показать уведомление
      </Button>
      <ToasterComponent />
    </ToasterProvider>
  );
}
```
